CREATE TABLE current_review_packages (connection_name TEXT NOT NULL, library_name TEXT NOT NULL, item_id TEXT NOT NULL, proposal_set_id TEXT REFERENCES proposal_sets(proposal_set_id), report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), review_case_id TEXT REFERENCES review_cases(review_case_id), checkpoint INTEGER CHECK(checkpoint IS NULL OR checkpoint>=1), outcome TEXT NOT NULL CHECK(outcome IN ('report_only','evidence_only','admitted','superseded','no_case','retired')), CHECK ((outcome IN ('report_only','evidence_only') AND proposal_set_id IS NULL AND review_case_id IS NULL AND checkpoint IS NULL) OR (outcome IN ('admitted','superseded') AND proposal_set_id IS NOT NULL AND review_case_id IS NOT NULL AND checkpoint IS NOT NULL) OR (outcome IN ('no_case','retired') AND proposal_set_id IS NOT NULL AND review_case_id IS NULL AND checkpoint IS NOT NULL)), PRIMARY KEY(connection_name,library_name,item_id));
