CREATE TABLE field_effect_events (event_id TEXT PRIMARY KEY NOT NULL CHECK(event_id GLOB 'effect_event_[0-9a-f]*' AND length(event_id)=77), plan_id TEXT NOT NULL REFERENCES field_effects(plan_id), sequence INTEGER NOT NULL CHECK(sequence>=1), kind TEXT NOT NULL CHECK(kind IN ('planned','claimed','applying','reconciling','retryable','verified','stale','superseded','abandoned')), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 131072), UNIQUE(plan_id,sequence));
CREATE TABLE field_effect_manual_holds (review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), destination TEXT NOT NULL CHECK(length(destination) BETWEEN 1 AND 64), active INTEGER NOT NULL CHECK(active IN (0,1)), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096), PRIMARY KEY(review_case_id,destination));
CREATE TABLE field_effect_no_changes (decision_id TEXT PRIMARY KEY NOT NULL, review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), report_id TEXT NOT NULL REFERENCES metadata_reports(report_id), connection_name TEXT NOT NULL, library_name TEXT NOT NULL, work_id TEXT NOT NULL, destination TEXT NOT NULL, target_fingerprint TEXT NOT NULL, target_version TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('human','automatic_policy')), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), event_id TEXT NOT NULL UNIQUE) WITHOUT ROWID;
CREATE TABLE field_effect_suspensions (scope TEXT NOT NULL CHECK(scope IN ('connection','destination')), connection_name TEXT NOT NULL CHECK(length(connection_name) BETWEEN 1 AND 128), destination TEXT NOT NULL CHECK(length(destination)<=64 AND ((scope='connection' AND destination='') OR (scope='destination' AND length(destination)>=1))), reason TEXT NOT NULL CHECK(reason IN ('connection_unavailable','insufficient_permission','field_unavailable','unexpected_effect_behavior')), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096), PRIMARY KEY(scope,connection_name,destination));
CREATE TABLE field_effects (plan_id TEXT PRIMARY KEY NOT NULL CHECK(plan_id GLOB 'effect_plan_[0-9a-f]*' AND length(plan_id)=76), decision_id TEXT NOT NULL, connection_name TEXT NOT NULL, library_name TEXT NOT NULL, work_id TEXT NOT NULL, destination TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('planned','claimed','applying','reconciling','retryable','verified','stale','superseded','abandoned')), attempt INTEGER NOT NULL CHECK(attempt BETWEEN 0 AND 3), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 131072));
CREATE TABLE human_decision_events (event_id TEXT PRIMARY KEY NOT NULL CHECK(event_id GLOB 'human_decision_event_[0-9a-f]*' AND length(event_id)=85), decision_id TEXT NOT NULL UNIQUE REFERENCES human_decisions(decision_id), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), destination TEXT NOT NULL CHECK(length(destination) BETWEEN 1 AND 64), actor TEXT NOT NULL CHECK(actor='owner'), kind TEXT NOT NULL CHECK(kind='human_decision_recorded'), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 65536));
CREATE TABLE human_decisions (ordinal INTEGER PRIMARY KEY NOT NULL, decision_id TEXT NOT NULL UNIQUE CHECK(decision_id GLOB 'human_decision_[0-9a-f]*' AND length(decision_id)=79), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), proposal_id TEXT NOT NULL CHECK(proposal_id GLOB 'review_proposal_[0-9a-f]*' AND length(proposal_id)=80), target_fingerprint TEXT NOT NULL CHECK(length(target_fingerprint)=64 AND target_fingerprint NOT GLOB '*[^0-9a-f]*'), destination TEXT NOT NULL CHECK(length(destination) BETWEEN 1 AND 64), actor TEXT NOT NULL CHECK(actor='owner'), outcome TEXT NOT NULL CHECK(outcome IN ('accept','keep_current','reject')), selected_value_document TEXT NOT NULL CHECK(typeof(selected_value_document)='text' AND length(CAST(selected_value_document AS BLOB)) BETWEEN 4 AND 32768), idempotency_digest TEXT NOT NULL UNIQUE CHECK(length(idempotency_digest)=64 AND idempotency_digest NOT GLOB '*[^0-9a-f]*'), request_digest TEXT NOT NULL CHECK(length(request_digest)=64 AND request_digest NOT GLOB '*[^0-9a-f]*'), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 65536));
CREATE TABLE metadata_policy_drafts (policy_id TEXT PRIMARY KEY NOT NULL CHECK (policy_id GLOB 'policy_[0-9a-f]*' AND length(policy_id)=71), document TEXT NOT NULL CHECK (typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 16384));
